def solve(rows):
    totals = {}
    for row in rows:
        key, amount, void = row
        if void:
            continue
        if abs(amount) < 7:
            continue
        totals[key] = totals.get(key, 0) + amount
    result = [[key, total] for key, total in totals.items() if total != 0]
    result.sort(key=lambda item: item[0])
    return result

